// Кэш предзагруженных объектов Image в памяти браузера, чтобы они никогда не выгружались сборщиком мусора
window._preloadedImagesCache = window._preloadedImagesCache || {};

function preloadSingleUrl(url, highPriority = false) {
  if (!url) return Promise.resolve();
  if (window._preloadedImagesCache[url]) return Promise.resolve();
  return new Promise((resolve) => {
    const img = new Image();
    if (highPriority) img.fetchPriority = "high";
    img.decoding = "async";
    img.onload = () => resolve();
    img.onerror = () => resolve();
    img.src = url;
    window._preloadedImagesCache[url] = img;
  });
}

// Моментальная предзагрузка всех фото при входе в режим (первые 4 вопроса — с высоким приоритетом, остальные параллельно)
async function preloadModeImages(mode, countriesList) {
  if (!Array.isArray(countriesList) || countriesList.length === 0) return;

  const getUrlForCountry = (c) => {
    const code = c.code || c;
    if (mode === "food") return getFoodImage(code);
    if (mode === "leaders") return getLeaderImage(code);
    if (mode === "flags" && typeof getFlagUrl === "function") return getFlagUrl(code);
    return null;
  };

  const urls = countriesList.map(getUrlForCountry).filter(Boolean);
  if (urls.length === 0) return;

  // Ждём загрузки первых 3 фото (максимум 450 мс), а все остальные вопросы раунда грузим сразу параллельно в кэш!
  const firstBatch = urls.slice(0, 3).map(u => preloadSingleUrl(u, true));
  urls.slice(3).forEach(u => preloadSingleUrl(u, false));

  await Promise.race([
    Promise.all(firstBatch),
    new Promise(r => setTimeout(r, 450))
  ]);
}

// Фоновая прогревка кэша при запуске приложения (постепенно подгружает флаги и портреты)
function preloadAllMediaInBackground() {
  if (typeof DB === "undefined" || !Array.isArray(DB)) return;
  let idx = 0;
  function loadNextBatch() {
    const slice = DB.slice(idx, idx + 8);
    if (slice.length === 0) return;
    slice.forEach(c => {
      if (typeof getFlagUrl === "function") preloadSingleUrl(getFlagUrl(c.code), false);
      if (LEADER_IMAGES[c.code]) preloadSingleUrl(LEADER_IMAGES[c.code], false);
      if (FOOD_IMAGES[c.code]) preloadSingleUrl(FOOD_IMAGES[c.code], false);
    });
    idx += 8;
    if (idx < DB.length) {
      setTimeout(loadNextBatch, 300);
    }
  }
  setTimeout(loadNextBatch, 800);
}

// Функция безопасного получения фото главного блюда (только для лёгкого и среднего уровней)
function getFoodImage(code) {
  if (typeof FOOD_IMAGES !== "undefined" && FOOD_IMAGES[code]) {
    return FOOD_IMAGES[code];
  }
  return null;
}

// Функция безопасного получения портрета действующего главы государства (2022+, без флагов и гербов)
function getLeaderImage(code) {
  if (typeof LEADER_IMAGES !== "undefined" && LEADER_IMAGES[code]) {
    return LEADER_IMAGES[code];
  }
  return null;
}

document.addEventListener("DOMContentLoaded", () => {
  preloadAllMediaInBackground();
});
